//! The conformance suite of the Rust port slice 1.
//!
//! Every case stands recorded from the Python reading of this
//! repository in conformance/port1_cases.json, regenerated by
//! the generator the round keeps in its scratch record and
//! never edited by hand. Boundary cases where the Python
//! command crashes carry the port's stated answers, marked in
//! the recordings. The census constants below pin the size of
//! each section so a thinned recording fails here rather than
//! passing quietly.

use std::path::PathBuf;

use deadgate::dates::{instant_isoformat, parse_timestamp_micros};
use deadgate::ingest::{history_window, load_history, load_protection, load_workflows, Workflow};
use deadgate::jsonvalue::{parse_json, JsonValue};
use deadgate::pytext::PyText;
use deadgate::reconcile::workflow_fires;
use deadgate::report::{build_report, render_json, render_markdown};
use deadgate::yaml::{parse_yaml, python_float_text, python_repr, python_str};
use deadgate::yamlvalue::{YamlKey, YamlValue};

fn recordings() -> JsonValue {
    parse_json(include_str!("conformance/port1_cases.json")).expect("the recordings decode")
}

fn section(name: &str) -> Vec<JsonValue> {
    let all = recordings();
    let sections = all.get("sections").expect("sections stand");
    sections
        .get(name)
        .and_then(|value| value.as_list())
        .unwrap_or_else(|| panic!("section {name} stands"))
        .clone()
}

fn field<'a>(value: &'a JsonValue, key: &str) -> &'a JsonValue {
    value
        .get(key)
        .unwrap_or_else(|| panic!("field {key} stands on {value:?}"))
}

fn field_text<'a>(value: &'a JsonValue, key: &str) -> &'a str {
    field(value, key)
        .as_text()
        .unwrap_or_else(|| panic!("field {key} is text"))
}

fn case_name(case: &JsonValue, fallback: &str) -> String {
    case.get("name")
        .and_then(|value| value.as_text())
        .unwrap_or(fallback)
        .to_string()
}

fn temp_root(section: &str, index: usize) -> PathBuf {
    let root = std::env::temp_dir().join(format!(
        "deadgate-conformance-{}-{section}-{index}",
        std::process::id()
    ));
    if root.exists() {
        std::fs::remove_dir_all(&root).expect("clear the case folder");
    }
    std::fs::create_dir_all(&root).expect("make the case folder");
    root
}

// ----------------------------------------------------------------
// Tagged encodings, the mirror of the generator's.
// ----------------------------------------------------------------

fn str_tag(text: &str) -> JsonValue {
    if text.chars().all(|ch| (0x20..=0x7E).contains(&(ch as u32))) {
        JsonValue::object(vec![
            ("t", JsonValue::text("str")),
            ("v", JsonValue::text(text)),
        ])
    } else {
        JsonValue::object(vec![
            ("t", JsonValue::text("strcp")),
            (
                "v",
                JsonValue::List(
                    text.chars()
                        .map(|ch| JsonValue::Int(ch as u32 as i64))
                        .collect(),
                ),
            ),
        ])
    }
}

fn float_tag(value: f64) -> JsonValue {
    let word = if value.is_nan() {
        "nan".to_string()
    } else if value.is_infinite() {
        if value < 0.0 {
            "-inf".to_string()
        } else {
            "inf".to_string()
        }
    } else {
        python_float_text(value)
    };
    JsonValue::object(vec![
        ("t", JsonValue::text("float")),
        ("v", JsonValue::text(word)),
    ])
}

fn tag_json(value: &JsonValue) -> JsonValue {
    match value {
        JsonValue::Null => JsonValue::object(vec![("t", JsonValue::text("null"))]),
        JsonValue::Bool(flag) => JsonValue::object(vec![
            ("t", JsonValue::text("bool")),
            ("v", JsonValue::Bool(*flag)),
        ]),
        JsonValue::Int(integer) => JsonValue::object(vec![
            ("t", JsonValue::text("int")),
            ("v", JsonValue::text(integer.to_string())),
        ]),
        JsonValue::BigInt(text) => JsonValue::object(vec![
            ("t", JsonValue::text("int")),
            ("v", JsonValue::text(text.clone())),
        ]),
        JsonValue::Float(number) => float_tag(*number),
        JsonValue::Text(text) => str_tag(text),
        JsonValue::PointText(text) => JsonValue::object(vec![
            ("t", JsonValue::text("strcp")),
            (
                "v",
                JsonValue::List(
                    text.points()
                        .iter()
                        .map(|point| JsonValue::Int(i64::from(*point)))
                        .collect(),
                ),
            ),
        ]),
        JsonValue::List(items) => JsonValue::object(vec![
            ("t", JsonValue::text("list")),
            ("v", JsonValue::List(items.iter().map(tag_json).collect())),
        ]),
        JsonValue::Object(pairs) => JsonValue::object(vec![
            ("t", JsonValue::text("obj")),
            (
                "v",
                JsonValue::List(
                    pairs
                        .iter()
                        .map(|(key, item)| JsonValue::List(vec![str_tag(key), tag_json(item)]))
                        .collect(),
                ),
            ),
        ]),
    }
}

fn tag_yaml(value: &YamlValue) -> JsonValue {
    match value {
        YamlValue::Null => JsonValue::object(vec![("t", JsonValue::text("null"))]),
        YamlValue::Bool(flag) => JsonValue::object(vec![
            ("t", JsonValue::text("bool")),
            ("v", JsonValue::Bool(*flag)),
        ]),
        YamlValue::Int(integer) => JsonValue::object(vec![
            ("t", JsonValue::text("int")),
            ("v", JsonValue::text(integer.to_string())),
        ]),
        YamlValue::BigInt(text) => JsonValue::object(vec![
            ("t", JsonValue::text("int")),
            ("v", JsonValue::text(text.clone())),
        ]),
        YamlValue::Float(number) => float_tag(*number),
        YamlValue::Text(text) => str_tag(text),
        YamlValue::Date(day) => JsonValue::object(vec![
            ("t", JsonValue::text("date")),
            (
                "v",
                JsonValue::text(deadgate::dates::date_text_of_instant(
                    *day as i128 * 86_400_000_000,
                )),
            ),
        ]),
        YamlValue::NaiveDateTime(instant) => JsonValue::object(vec![
            ("t", JsonValue::text("naive")),
            ("micros", JsonValue::text(instant.to_string())),
        ]),
        YamlValue::AwareDateTime(instant, offset) => JsonValue::object(vec![
            ("t", JsonValue::text("aware")),
            ("micros", JsonValue::text(instant.to_string())),
            ("offset", JsonValue::Int(*offset)),
        ]),
        YamlValue::List(items) => JsonValue::object(vec![
            ("t", JsonValue::text("list")),
            ("v", JsonValue::List(items.iter().map(tag_yaml).collect())),
        ]),
        YamlValue::Mapping(pairs) => JsonValue::object(vec![
            ("t", JsonValue::text("obj")),
            (
                "v",
                JsonValue::List(
                    pairs
                        .iter()
                        .map(|(key, item)| {
                            JsonValue::List(vec![
                                tag_yaml(&deadgate::yamlvalue::key_to_value(key)),
                                tag_yaml(item),
                            ])
                        })
                        .collect(),
                ),
            ),
        ]),
    }
}

/// Run a section body on a thread with a stack sized for the
/// nesting boundary cases, the recursive readers needing the
/// room their depth bound allows.
fn on_big_stack(body: impl FnOnce() + Send + 'static) {
    std::thread::Builder::new()
        .stack_size(256 * 1024 * 1024)
        .spawn(body)
        .expect("spawn the section thread")
        .join()
        .expect("the section holds");
}

fn base64_decode(text: &str) -> Vec<u8> {
    let mut values: Vec<u8> = Vec::new();
    let mut buffer: u32 = 0;
    let mut bits = 0;
    for ch in text.chars() {
        let digit = match ch {
            'A'..='Z' => ch as u32 - 'A' as u32,
            'a'..='z' => ch as u32 - 'a' as u32 + 26,
            '0'..='9' => ch as u32 - '0' as u32 + 52,
            '+' => 62,
            '/' => 63,
            '=' => break,
            _ => continue,
        };
        buffer = (buffer << 6) | digit;
        bits += 6;
        if bits >= 8 {
            bits -= 8;
            values.push((buffer >> bits) as u8);
        }
    }
    values
}

