#[test]
fn census_stands() {
    assert_eq!(section("protection").len(), 29, "protection census");
    assert_eq!(section("history").len(), 21, "history census");
    assert_eq!(section("timestamps").len(), 76, "timestamps census");
    assert_eq!(section("workflows").len(), 36, "workflows census");
    assert_eq!(section("reports").len(), 15, "reports census");
    assert_eq!(section("patterns").len(), 66, "patterns census");
    assert_eq!(section("yaml_values").len(), 193, "yaml values census");
    assert_eq!(section("yaml_strings").len(), 32, "yaml strings census");
    assert_eq!(section("json_values").len(), 35, "json values census");
}

