#[test]
fn protection_cases_hold() {
    for (index, case) in section("protection").iter().enumerate() {
        let name = case_name(case, "protection");
        let root = temp_root("protection", index);
        let path = root.join("protection.json");
        if case.get("missing").is_none() {
            if let Some(encoded) = case.get("file_b64") {
                let bytes = base64_decode(encoded.as_text().expect("base64 text"));
                std::fs::write(&path, bytes).expect("write bytes");
            } else {
                std::fs::write(&path, field_text(case, "text")).expect("write text");
            }
        }
        let path_text = path.to_string_lossy().into_owned();
        let expect = field(case, "expect");
        match load_protection(&path) {
            Ok(contexts) => {
                let wanted = field(expect, "ok").as_list().expect("recorded contexts");
                let wanted: Vec<&str> = wanted.iter().filter_map(|item| item.as_text()).collect();
                assert_eq!(contexts, wanted, "case {name}");
            }
            Err(error) => {
                let wanted = field_text(expect, "err").replace("{PATH}", &path_text);
                assert_eq!(error.message, wanted, "case {name}");
            }
        }
    }
}

#[test]
fn history_cases_hold() {
    for (index, case) in section("history").iter().enumerate() {
        let name = case_name(case, "history");
        let root = temp_root("history", index);
        let path = root.join("history.json");
        std::fs::write(&path, field_text(case, "text")).expect("write text");
        let path_text = path.to_string_lossy().into_owned();
        let expect = field(case, "expect");
        match load_history(&path) {
            Ok(records) => {
                let wanted = field(expect, "ok");
                let tagged: Vec<JsonValue> = records
                    .iter()
                    .map(|record| {
                        JsonValue::object(vec![
                            ("name", JsonValue::text(record.name.clone())),
                            ("workflow_name", tag_json(&record.workflow_name)),
                            ("status", tag_json(&record.status)),
                            ("conclusion", tag_json(&record.conclusion)),
                            (
                                "started",
                                match record.started_at {
                                    Some(instant) => JsonValue::text(instant.to_string()),
                                    None => JsonValue::Null,
                                },
                            ),
                            (
                                "completed",
                                match record.completed_at {
                                    Some(instant) => JsonValue::text(instant.to_string()),
                                    None => JsonValue::Null,
                                },
                            ),
                        ])
                    })
                    .collect();
                let wanted_records = field(wanted, "records").clone();
                assert_eq!(
                    JsonValue::List(tagged),
                    wanted_records,
                    "case {name} records"
                );
                let window = history_window(&records).unwrap_or(JsonValue::Null);
                assert_eq!(
                    tag_json(&window),
                    field(wanted, "window").clone(),
                    "case {name} window"
                );
            }
            Err(error) => {
                let wanted = field_text(expect, "err").replace("{PATH}", &path_text);
                assert_eq!(error.message, wanted, "case {name}");
            }
        }
    }
}

#[test]
fn timestamp_cases_hold() {
    for case in section("timestamps").iter() {
        let text = field_text(case, "text");
        let expect = field(case, "expect");
        match (parse_timestamp_micros(text), expect.get("ok")) {
            (Some(instant), Some(_)) => {
                assert_eq!(
                    instant_isoformat(instant),
                    field_text(expect, "ok"),
                    "timestamp {text:?} spelling"
                );
                assert_eq!(
                    instant.to_string(),
                    field_text(expect, "micros"),
                    "timestamp {text:?} instant"
                );
            }
            (None, None) => {}
            (actual, _) => {
                panic!("timestamp {text:?} read as {actual:?} against the recording")
            }
        }
    }
}

fn write_workflows(root: &std::path::Path, case: &JsonValue) -> PathBuf {
    let folder = root.join("workflows");
    std::fs::create_dir_all(&folder).expect("make workflows folder");
    let files = field(case, "files");
    if let Some(pairs) = files.as_object() {
        for (name, text) in pairs {
            std::fs::write(folder.join(name), text.as_text().expect("file text"))
                .expect("write workflow file");
        }
    }
    folder
}

fn substitute(message: &str, replacements: &[(&str, &str)]) -> String {
    let mut out = message.to_string();
    for (token, value) in replacements {
        out = out.replace(token, value);
    }
    out
}

#[test]
fn workflow_cases_hold() {
    for (index, case) in section("workflows").iter().enumerate() {
        let name = case_name(case, "workflows");
        let root = temp_root("workflows", index);
        let folder = write_workflows(&root, case);
        let folder_text = folder.to_string_lossy().into_owned();
        let expect = field(case, "expect");
        match load_workflows(&folder) {
            Ok(workflows) => {
                let tagged: Vec<JsonValue> = workflows
                    .iter()
                    .map(|workflow| {
                        JsonValue::object(vec![
                            (
                                "workflow",
                                JsonValue::text(
                                    workflow
                                        .workflow
                                        .plain()
                                        .expect("the recorded workflow name is plain"),
                                ),
                            ),
                            (
                                "file",
                                JsonValue::text(
                                    workflow
                                        .file
                                        .plain()
                                        .expect("the recorded file name is plain"),
                                ),
                            ),
                            ("triggers", tag_yaml(&workflow.triggers)),
                            (
                                "jobs",
                                JsonValue::List(
                                    workflow
                                        .jobs
                                        .iter()
                                        .map(|(job_id, job)| {
                                            JsonValue::List(vec![
                                                JsonValue::text(job_id.clone()),
                                                JsonValue::object(vec![
                                                    ("job", JsonValue::text(job.job.clone())),
                                                    (
                                                        "job_name",
                                                        JsonValue::text(job.job_name.clone()),
                                                    ),
                                                    ("has_if", JsonValue::Bool(job.has_if)),
                                                    (
                                                        "combinations",
                                                        match &job.combinations {
                                                            Some(list) => JsonValue::List(
                                                                list.iter()
                                                                    .map(|item| {
                                                                        JsonValue::text(
                                                                            item.clone(),
                                                                        )
                                                                    })
                                                                    .collect(),
                                                            ),
                                                            None => JsonValue::Null,
                                                        },
                                                    ),
                                                ]),
                                            ])
                                        })
                                        .collect(),
                                ),
                            ),
                        ])
                    })
                    .collect();
                assert_eq!(
                    JsonValue::List(tagged),
                    field(expect, "ok").clone(),
                    "case {name}"
                );
            }
            Err(error) => {
                if expect.get("err").is_none() {
                    panic!(
                        "case {name} refused with {:?} against an ok recording",
                        error.message
                    );
                }
                let mut replacements: Vec<(String, String)> =
                    vec![("{WROOT}".to_string(), folder_text.clone())];
                if let Some(pairs) = field(case, "files").as_object() {
                    for (file_name, _) in pairs {
                        replacements.push((
                            format!("{{WFILE:{file_name}}}"),
                            folder.join(file_name).to_string_lossy().into_owned(),
                        ));
                    }
                }
                let pairs: Vec<(&str, &str)> = replacements
                    .iter()
                    .map(|(a, b)| (a.as_str(), b.as_str()))
                    .collect();
                let wanted = substitute(field_text(expect, "err"), &pairs);
                assert_eq!(error.message, wanted, "case {name}");
            }
        }
    }
}

#[test]
fn report_cases_hold() {
    for (index, case) in section("reports").iter().enumerate() {
        let name = case_name(case, "reports");
        let root = temp_root("reports", index);
        let protection = root.join("protection.json");
        std::fs::write(&protection, field_text(case, "protection")).expect("write protection");
        let folder = write_workflows(&root, case);
        let history = root.join("history.json");
        std::fs::write(&history, field_text(case, "history")).expect("write history");
        let branch = field_text(case, "branch");
        let expect = field(case, "expect");
        let protection_text = protection.to_string_lossy().into_owned();
        let history_text = history.to_string_lossy().into_owned();
        let folder_text = folder.to_string_lossy().into_owned();
        let run = (|| -> Result<JsonValue, deadgate::DeadgateError> {
            let contexts = load_protection(&protection)?;
            let workflows = load_workflows(&folder)?;
            let records = load_history(&history)?;
            let window = history_window(&records);
            build_report(
                &contexts,
                &workflows,
                &records,
                &PyText::from_plain(branch),
                window,
            )
        })();
        match run {
            Ok(report) => {
                let wanted = field(expect, "ok");
                assert_eq!(
                    render_json(&report),
                    field_text(wanted, "json"),
                    "case {name} json"
                );
                assert_eq!(
                    String::from_utf8(render_markdown(&report)).expect("markdown text"),
                    field_text(wanted, "markdown"),
                    "case {name} markdown"
                );
            }
            Err(error) => {
                let mut replacements: Vec<(String, String)> = vec![
                    ("{PATH}".to_string(), protection_text.clone()),
                    ("{HPATH}".to_string(), history_text.clone()),
                    ("{WROOT}".to_string(), folder_text.clone()),
                ];
                if let Some(pairs) = field(case, "files").as_object() {
                    for (file_name, _) in pairs {
                        replacements.push((
                            format!("{{WFILE:{file_name}}}"),
                            folder.join(file_name).to_string_lossy().into_owned(),
                        ));
                    }
                }
                let pairs: Vec<(&str, &str)> = replacements
                    .iter()
                    .map(|(a, b)| (a.as_str(), b.as_str()))
                    .collect();
                let wanted = substitute(field_text(expect, "err"), &pairs);
                assert_eq!(error.message, wanted, "case {name}");
            }
        }
    }
}

#[test]
fn pattern_cases_hold() {
    for case in section("patterns").iter() {
        let patterns: Vec<String> = field(case, "patterns")
            .as_list()
            .expect("patterns list")
            .iter()
            .filter_map(|item| item.as_text().map(|text| text.to_string()))
            .collect();
        let branch = field_text(case, "branch");
        let workflow = Workflow {
            workflow: PyText::from_plain("w"),
            file: PyText::from_plain("w.yml"),
            triggers: YamlValue::Mapping(vec![(
                YamlKey::Text("push".to_string()),
                YamlValue::Mapping(vec![(
                    YamlKey::Text("branches".to_string()),
                    YamlValue::List(
                        patterns
                            .iter()
                            .map(|item| YamlValue::Text(item.clone()))
                            .collect(),
                    ),
                )]),
            )]),
            jobs: Vec::new(),
        };
        let expect = field(case, "expect");
        match workflow_fires(&workflow, &PyText::from_plain(branch)) {
            Ok((fires, _)) => {
                let wanted = field(expect, "fires");
                assert_eq!(
                    JsonValue::Bool(fires),
                    wanted.clone(),
                    "patterns {patterns:?} on {branch}"
                );
            }
            Err(error) => {
                assert_eq!(
                    error.message,
                    field_text(expect, "err"),
                    "patterns {patterns:?} on {branch}"
                );
            }
        }
    }
}

