#[test]
fn binary_door_holds() {
    let root = temp_root("binary", 0);
    let protection = root.join("protection.json");
    std::fs::write(
        &protection,
        "{\"required_status_checks\": {\"checks\": [{\"context\": \"ci / build\"}]}}",
    )
    .expect("write protection");
    let folder = root.join("workflows");
    std::fs::create_dir_all(&folder).expect("make folder");
    std::fs::write(
        folder.join("ci.yml"),
        "name: ci\non: push\njobs:\n  build:\n    steps: []\n",
    )
    .expect("write workflow");
    let history = root.join("history.json");
    std::fs::write(
        &history,
        "{\"jobs\": [{\"name\": \"build\", \"workflow_name\": \"ci\", \"status\": \"completed\", \"conclusion\": \"success\", \"started_at\": \"2026-10-14T09:00:00Z\", \"completed_at\": \"2026-10-14T09:04:00Z\"}]}",
    )
    .expect("write history");
    let binary = env!("CARGO_BIN_EXE_deadgate");
    let output = std::process::Command::new(binary)
        .args([
            "--protection",
            protection.to_str().expect("path"),
            "--workflows",
            folder.to_str().expect("path"),
            "--history",
            history.to_str().expect("path"),
        ])
        .output()
        .expect("run the binary");
    assert!(output.status.success(), "the binary succeeds");
    let contexts = load_protection(&protection).expect("contexts");
    let workflows = load_workflows(&folder).expect("workflows");
    let records = load_history(&history).expect("records");
    let window = history_window(&records);
    let report = build_report(
        &contexts,
        &workflows,
        &records,
        &PyText::from_plain("main"),
        window,
    )
    .expect("report");
    assert_eq!(
        String::from_utf8(output.stdout).expect("stdout text"),
        render_json(&report),
        "the binary prints the library rendering"
    );
    // A refusal at the door exits two with the deadgate line.
    std::fs::write(
        &protection,
        "{\"required_status_checks\": {\"checks\": [{\"context\": \"a\", \"context\": \"b\"}]}}",
    )
    .expect("write duplicate protection");
    let refused = std::process::Command::new(binary)
        .args([
            "--protection",
            protection.to_str().expect("path"),
            "--workflows",
            folder.to_str().expect("path"),
            "--history",
            history.to_str().expect("path"),
        ])
        .output()
        .expect("run the binary");
    assert_eq!(refused.status.code(), Some(2), "the refusal exits two");
    let stderr = String::from_utf8(refused.stderr).expect("stderr text");
    assert!(
        stderr.starts_with("deadgate: protection export at "),
        "the refusal names the door, got {stderr}"
    );
    assert!(
        stderr.contains("carries the key context more than once"),
        "the refusal carries the R2-1 words, got {stderr}"
    );
}
